47	void OwnSplitChannel::tryLogSplit(const Poco::Message & msg)
48	{
49	    try
50	    {
51	        logSplit(msg);
52	    }
53	    /// It is better to catch the errors here in order to avoid
54	    /// breaking some functionality because of unexpected "File not
55	    /// found" (or similar) error.
56	    ///
57	    /// For example StorageDistributedDirectoryMonitor will mark batch
58	    /// as broken, some MergeTree code can also be affected.
59	    ///
60	    /// Also note, that we cannot log the exception here, since this
61	    /// will lead to recursion, using regular tryLogCurrentException().
62	    /// but let's log it into the stderr at least.
63	    catch (...)
64	    {
65	        LockMemoryExceptionInThread lock_memory_tracker(VariableContext::Global);
66	
67	        const std::string & exception_message = getCurrentExceptionMessage(true);
68	        const std::string & message = msg.getText();
69	
70	        /// NOTE: errors are ignored, since nothing can be done.
71	        writeRetry(STDERR_FILENO, "Cannot add message to the log: ");
72	        writeRetry(STDERR_FILENO, message.data(), message.size());
73	        writeRetry(STDERR_FILENO, "\n");
74	        writeRetry(STDERR_FILENO, exception_message.data(), exception_message.size());
75	        writeRetry(STDERR_FILENO, "\n");
76	    }
