11	std::function<size_t(size_t index)> GetPriorityForLoadBalancing::getPriorityFunc(LoadBalancing load_balance, size_t offset, size_t pool_size) const
12	{
13	    std::function<size_t(size_t index)> get_priority;
14	    switch (load_balance)
15	    {
16	        case LoadBalancing::NEAREST_HOSTNAME:
17	            if (hostname_differences.empty())
18	                throw Exception(ErrorCodes::LOGICAL_ERROR, "It's a bug: hostname_differences is not initialized");
19	            get_priority = [&](size_t i) { return hostname_differences[i]; };
20	            break;
21	        case LoadBalancing::IN_ORDER:
22	            get_priority = [](size_t i) { return i; };
23	            break;
24	        case LoadBalancing::RANDOM:
25	            break;
26	        case LoadBalancing::FIRST_OR_RANDOM:
27	            get_priority = [offset](size_t i) -> size_t { return i != offset; };
28	            break;
29	        case LoadBalancing::ROUND_ROBIN:
30	            if (last_used >= pool_size)
31	                last_used = 0;
32	            ++last_used;
33	            /* Consider pool_size equals to 5
34	             * last_used = 1 -> get_priority: 0 1 2 3 4
35	             * last_used = 2 -> get_priority: 4 0 1 2 3
36	             * last_used = 3 -> get_priority: 4 3 0 1 2
37	             * ...
38	             * */
39	            get_priority = [&](size_t i)
40	            {
41	                ++i;
42	                return i < last_used ? pool_size - i : i - last_used;
43	            };
44	            break;
45	    }
46	    return get_priority;
47	}
