13	class HashingReadBuffer : public IHashingBuffer<ReadBuffer>
14	{
15	public:
16	    explicit HashingReadBuffer(ReadBuffer & in_, size_t block_size_ = DBMS_DEFAULT_HASHING_BLOCK_SIZE)
17	        : IHashingBuffer<ReadBuffer>(block_size_), in(in_)
18	    {
19	        working_buffer = in.buffer();
20	        pos = in.position();
21	
22	        /// calculate hash from the data already read
23	        if (!working_buffer.empty())
24	        {
25	            calculateHash(pos, working_buffer.end() - pos);
26	        }
27	    }
28	
29	private:
30	    bool nextImpl() override
31	    {
32	        in.position() = pos;
33	        bool res = in.next();
34	        working_buffer = in.buffer();
35	        pos = in.position();
36	
37	        // `pos` may be different from working_buffer.begin() when using sophisticated ReadBuffers.
38	        calculateHash(pos, working_buffer.end() - pos);
39	
40	        return res;
41	    }
42	
43	    ReadBuffer & in;
44	};
