60	bool ConcatSeekableReadBuffer::nextImpl()
61	{
62	    if (current < buffers.size())
63	    {
64	        buffers[current].in->position() = pos;
65	        while ((current < buffers.size()) && buffers[current].in->eof())
66	        {
67	            current_start_pos += buffers[current++].size;
68	            if (current < buffers.size())
69	                buffers[current].in->seek(0, SEEK_SET);
70	        }
71	    }
72	
73	    if (current >= buffers.size())
74	    {
75	        current_start_pos = total_size;
76	        set(nullptr, 0);
77	        return false;
78	    }
79	
80	    working_buffer = buffers[current].in->buffer();
81	    pos = buffers[current].in->position();
82	    return true;
