93	off_t ConcatSeekableReadBuffer::seek(off_t off, int whence)
94	{
95	    off_t new_position;
96	    off_t current_position = getPosition();
97	    if (whence == SEEK_SET)
98	        new_position = off;
99	    else if (whence == SEEK_CUR)
100	        new_position = current_position + off;
101	    else
102	        throw Exception("ConcatSeekableReadBuffer::seek expects SEEK_SET or SEEK_CUR as whence", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
103	
104	    if (new_position < 0)
105	        throw Exception("SEEK_SET underflow: off = " + std::to_string(off), ErrorCodes::ARGUMENT_OUT_OF_BOUND);
106	    if (static_cast<UInt64>(new_position) > total_size)
107	        throw Exception("SEEK_CUR shift out of bounds", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
108	
109	    if (static_cast<UInt64>(new_position) == total_size)
110	    {
111	        current = buffers.size();
112	        current_start_pos = total_size;
113	        set(nullptr, 0);
114	        return new_position;
115	    }
116	
117	    off_t change_position = new_position - current_position;
118	    if ((working_buffer.begin() <= pos + change_position) && (pos + change_position <= working_buffer.end()))
119	    {
120	        /// Position is still inside the same working buffer.
121	        pos += change_position;
122	        assert(pos >= working_buffer.begin());
123	        assert(pos <= working_buffer.end());
124	        return new_position;
125	    }
126	
127	    while (new_position < static_cast<off_t>(current_start_pos))
128	        current_start_pos -= buffers[--current].size;
129	
130	    while (new_position >= static_cast<off_t>(current_start_pos + buffers[current].size))
131	        current_start_pos += buffers[current++].size;
132	
133	    buffers[current].in->seek(new_position - current_start_pos, SEEK_SET);
134	    working_buffer = buffers[current].in->buffer();
135	    pos = buffers[current].in->position();
136	    return new_position;
137	}
